#!/usr/bin/env python3
"""Generate hypr/hyprlock.conf for every monitor with its own scale.

hyprlock sizes are in physical pixels, so a 2x panel needs everything doubled.
Edit MONITORS / the template below, then run:  python3 ~/.config/hypr/hyprlock-gen.py
"""
from pathlib import Path

# (hyprlock monitor selector, scale). Same monitors as hyprland.lua.
MONITORS = [
    ("eDP-1", 2.0),
    ("desc:Dell Inc. DELL U2412M 0FFXD4152LWL", 1.0),
]

HEADER = """# hypr-cosmic-shell: hyprlock in the COSMIC Dark theme (colors from shell/Theme.qml).
# GENERATED by ~/.config/hypr/hyprlock-gen.py, edit that file instead and re-run it.
# hyprlock still uses the hyprlang format, so this stays a .conf file.
# Used by hypridle.conf (lock_cmd); SUPER CTRL L → loginctl lock-session → hypridle.

$accent    = rgb(ffad00)
$text      = rgb(eeeeee)
$textDim   = rgba(255, 255, 255, 0.65)
$card      = rgba(27, 27, 27, 0.55)
$cardLine  = rgba(255, 255, 255, 0.12)
$component = rgba(54, 54, 54, 0.9)
$fail      = rgb(ffa09a)
$font      = Fira Sans
$icons     = Material Symbols Rounded

general {
    hide_cursor = true
    ignore_empty_input = true
    fractional_scaling = 0
}

auth {
    pam:module = hyprlock
}

animations {
    enabled = true
    bezier = cosmic, 0.25, 0.1, 0.25, 1
    animation = fadeIn, 1, 5, cosmic
    animation = fadeOut, 1, 4, cosmic
    animation = inputFieldColors, 1, 3, cosmic
    animation = inputFieldDots, 1, 2, cosmic
}

# Blurred, dimmed screenshot of each monitor
background {
    monitor =
    path = screenshot
    color = rgb(1b1b1b)
    blur_passes = 3
    blur_size = 10
    brightness = 0.5
    contrast = 0.95
    vibrancy = 0.2
    noise = 0.01
}
"""

TEMPLATE = """
# ======================= {mon} (scale {scale}) =======================

# Clock: bold hours, amber colon, light minutes
label {{
    monitor = {mon}
    text = cmd[update:1000] echo "<b>$(date +%H)</b><span foreground='##ffad00'>:</span>$(date +%M)"
    color = $text
    font_size = {clock}
    font_family = $font Light
    position = 0, {clock_y}
    halign = center
    valign = center
    shadow_passes = 3
    shadow_size = {shadow}
    shadow_color = rgba(0, 0, 0, 0.45)
}}

# Date
label {{
    monitor = {mon}
    text = cmd[update:60000] LC_TIME=en_US.UTF-8 date +"%A, %B %-d"
    color = $text
    font_size = {date}
    font_family = $font
    position = 0, {date_y}
    halign = center
    valign = center
    shadow_passes = 2
    shadow_size = {shadow}
}}

# Frosted card behind the login part
shape {{
    monitor = {mon}
    size = {card_w}, {card_h}
    color = $card
    rounding = {card_r}
    border_size = {border}
    border_color = $cardLine
    position = 0, {card_y}
    halign = center
    valign = center
    shadow_passes = 2
    shadow_size = {shadow}
    shadow_color = rgba(0, 0, 0, 0.3)
}}

# Avatar: amber circle with the first letter of the user name
shape {{
    monitor = {mon}
    size = {avatar}, {avatar}
    color = $accent
    rounding = -1
    position = 0, {avatar_y}
    halign = center
    valign = center
}}
label {{
    monitor = {mon}
    text = cmd[update:0] n=$(getent passwd "$USER" | cut -d: -f5 | cut -d, -f1); n=${{n:-$USER}}; printf '%s' "$n" | cut -c1 | tr '[:lower:]' '[:upper:]'
    color = rgb(000000)
    font_size = {avatar_font}
    font_family = $font SemiBold
    position = 0, {avatar_y}
    halign = center
    valign = center
}}

# Greeting
label {{
    monitor = {mon}
    text = cmd[update:60000] h=$(date +%-H); n=$(getent passwd "$USER" | cut -d: -f5 | cut -d, -f1 | cut -d' ' -f1); n=${{n:-$USER}}; n="$(printf '%s' "$n" | cut -c1 | tr '[:lower:]' '[:upper:]')$(printf '%s' "$n" | cut -c2-)"; if [ $h -lt 5 ] || [ $h -ge 18 ]; then g="Good evening"; elif [ $h -lt 12 ]; then g="Good morning"; else g="Good afternoon"; fi; echo "$g, $n"
    color = $text
    font_size = {greet}
    font_family = $font Medium
    position = 0, {greet_y}
    halign = center
    valign = center
}}

# Password field
input-field {{
    monitor = {mon}
    size = {input_w}, {input_h}
    outline_thickness = {border2}
    rounding = -1
    outer_color = $cardLine
    inner_color = $component
    font_color = $text
    font_family = $font
    check_color = $accent
    fail_color = $fail
    capslock_color = rgb(ffa37d)
    dots_size = 0.22
    dots_spacing = 0.35
    dots_center = true
    fade_on_empty = false
    placeholder_text = <span foreground="##ffffffa6">Enter password</span>
    fail_text = <span foreground="##ffa09a">$PAMFAIL</span>
    position = 0, {input_y}
    halign = center
    valign = center
}}

# Bottom bar: now playing (left), battery (right)
label {{
    monitor = {mon}
    text = cmd[update:2000] t=$(playerctl metadata --format '{{{{artist}}}} – {{{{title}}}}' 2>/dev/null | cut -c1-60); [ -n "$t" ] && echo "<span font_family='Material Symbols Rounded'>music_note</span>  $t"
    color = $textDim
    font_size = {small}
    font_family = $font
    position = {margin}, {margin}
    halign = left
    valign = bottom
}}
label {{
    monitor = {mon}
    text = cmd[update:30000] b=$(cat /sys/class/power_supply/BAT0/capacity 2>/dev/null) || exit 0; s=$(cat /sys/class/power_supply/BAT0/status); i=battery_full; [ "$b" -lt 80 ] && i=battery_5_bar; [ "$b" -lt 50 ] && i=battery_3_bar; [ "$b" -lt 20 ] && i=battery_1_bar; [ "$s" = Charging ] && i=battery_charging_full; echo "<span font_family='Material Symbols Rounded'>$i</span>  $b%"
    color = $textDim
    font_size = {small}
    font_family = $font
    position = -{margin}, {margin}
    halign = right
    valign = bottom
}}
"""

# Sizes at scale 1 (logical pixels)
BASE = dict(clock=104, clock_y=210, date=19, date_y=120, shadow=6,
            card_w=380, card_h=230, card_r=24, card_y=-110, border=1, border2=2,
            avatar=64, avatar_y=-35, avatar_font=26,
            greet=17, greet_y=-90,
            input_w=300, input_h=46, input_y=-155,
            small=12, margin=24)

out = [HEADER]
for mon, scale in MONITORS:
    vals = {k: round(v * scale) for k, v in BASE.items()}
    out.append(TEMPLATE.format(mon=mon, scale=scale, **vals))
target = Path(__file__).with_name("hyprlock.conf")
target.write_text("".join(out))
print(f"wrote {target}")
